/**
 * Which glyphs the panel draws, and how big their boxes are, in the theme that is on.
 *
 * THE FOOTPRINT IS THE THEME'S, NOT THE GLYPH'S. ORIGINAL traces its glyphs from a
 * terminal font and inherits that font's proportions — a tall narrow battery, a wide
 * camera; GLASS uses a square grid. The panel lays out against these numbers in half a
 * dozen places, so asking the icon directly is asking the wrong question: it answers for
 * one theme and is silently wrong in the other.
 */
object Glyphs {

    fun aspect(icon: PanelIcons.Icon, theme: PanelTheme): Float =
        if (theme.isGlass && GlassIcons.of(icon) != null) GlassIcons.ASPECT else icon.aspect
}
